Rules.InvariantScript:
UpdateIf(colFilters, true, {Selected: false});
Patch(colFilters, ThisItem, {Selected: true});
If(
    ThisItem.Kind = "L2",
    Set(varL2, ThisItem.Value),
    ThisItem.Kind = "Program",
    Set(varProgram, ThisItem.Value),
    Set(varHighOnly, ThisItem.Value = "High + Extreme")
)

ClearCollect(
    colRiskCells,
    ForAll(
        Sequence(25) As i,
        With(
            {
                p: 6 - RoundUp(i.Value / 5, 0),
                s: If(Mod(i.Value, 5) = 0, 5, Mod(i.Value, 5))
            },
            {
                Probability: p,
                Severity: s,
                Score: p * s,
                RiskCount: Coalesce(
                    LookUp(colRiskCounts, Probability = p && Severity = s).RiskCount,
                    0
                )
            }
        )
    )
)

ClearCollect(
    colRiskCells,
    ForAll(
        Sequence(25) As i,
        With(
            {
                p: 6 - RoundUp(i.Value / 5, 0),
                s: If(Mod(i.Value, 5) = 0, 5, Mod(i.Value, 5))
            },
            {
                Probability: p,
                Severity: s,
                Score: p * s,
                RiskCount: Coalesce(
                    LookUp(colRiskCounts, Probability = p && Severity = s).RiskCount,
                    0
                )
            }
        )
    )
)
